def priority(item: float, bins: np.ndarray) -> np.ndarray:
    if bins.size == 0:
        return np.array([], dtype=np.float64)
    remaining = bins - item
    valid = remaining >= 0
    max_bin = bins.max()
    scale = 1.0 / (max_bin + 1e-8)
    normalized_remaining = remaining / bins
    score = np.where(valid, -normalized_remaining + bins * scale, -np.inf)
    return score

